window.BAHALANA_CONTENT = {"cards": [{"id": "ch1_pondo_01", "chapter": 1, "pool": "ch1", "title": "Pondo ng Klase", "title_en": "The Class Fund", "tags": ["school", "integridad", "padrino"], "requires": null, "setup": "Iniwan ni Ma'am Lourdes ang kahon ng ambagan sa mesa niya at lumabas saglit. Bumulong si Pia, ang katabi mo: '₱20 lang, babayaran ko bukas. Walang makakaalam.'", "setup_en": "Ma'am Lourdes left the donation box on her desk and stepped out for a moment. Pia, your seatmate, whispers: 'Just ₱20, I'll pay you back tomorrow. No one will know.'", "choices": [{"label": "Huwag. Sabihin natin kay Ma'am.", "label_en": "No. Let's tell Ma'am.", "type": "honest", "roll": {"stat": "integridad", "dc": 8}, "success": {"text": "Sinabi ninyo kay Ma'am. Nainis si Pia, pero napansin ka ni Ma'am.", "text_en": "You tell Ma'am. Pia is upset, but Ma'am notices your honesty.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Sumbungera si Pia sa'yo. Nasaktan siya.", "text_en": "Pia snitches on you. She gets hurt.", "effects": {"stats": {"komunidad": -1}}}}, {"label": "Sige, isang beses lang.", "label_en": "Fine, just once.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 1, "integridad": -1}, "utang": 1}}, {"label": "Pabayaan, hindi ko kasalanan.", "label_en": "Leave it. Not my fault.", "type": "huwag", "roll": null, "effects": {"flags": ["saw_it"]}}], "callback": "saw_it -> Ch2 Card 3 (Pia asks for a bigger favor)."}, {"id": "ch1_baon_02", "chapter": 1, "pool": "ch1", "title": "Baon", "title_en": "Lunch Money", "tags": ["school", "komunidad", "pera"], "requires": null, "setup": "Tanghalian na. Si Rico, ang kaklaseng laging maaga, ay walang baon — nakalimutan daw ng nanay niya. May sobra kang tinapay at itlog. Tumingin siya sa pagkain mo, tapos sa'yo.", "setup_en": "It's lunchtime. Rico, the classmate who always arrives early, has no baon — he forgot, his mother said. You have extra bread and egg. He looks at your food, then at you.", "choices": [{"label": "Hati tayo.", "label_en": "Let's share.", "type": "collective", "roll": {"stat": "komunidad", "dc": 8}, "success": {"text": "Natawanan ni Rico. Magkasama kayong kumain.", "text_en": "Rico laughs with relief. You eat together.", "effects": {"stats": {"komunidad": 1}, "flags": ["shared_food"]}}, "fail": {"text": "Nahiya siya, pero natulungan mo pa rin siya.", "text_en": "He's embarrassed, but you still helped him.", "effects": {"flags": ["shared_food"]}}}, {"label": "Palit tayo ng meryenda.", "label_en": "Let's trade snacks.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 10}, "success": {"text": "Napasaya mo siya nang walang pang-iinsulto.", "text_en": "You cheer him up without embarrassing him.", "effects": {"stats": {"pera": 1, "komunidad": 1}}}, "fail": {"text": "'Ayaw ko ng palit,' sabi ni Rico. Mababang loob siya.", "text_en": "'I don't want a trade,' Rico says. He's proud.", "effects": {"flags": ["rico_proud"]}}}, {"label": "Hindi ko napansin.", "label_en": "I didn't notice.", "type": "huwag", "roll": null, "effects": {"flags": ["looked_away"]}}], "callback": "shared_food / looked_away -> Ch2 Card 7."}, {"id": "ch1_kopya_03", "chapter": 1, "pool": "ch1", "title": "Kopya", "title_en": "Cheat Sheet", "tags": ["school", "integridad", "utang"], "requires": null, "setup": "May quiz bukas at hindi nakapag-review si Bea, ang kaibigan mong magaling mag-drawing. 'Pahiram ng sagot mo mamaya, isang tingin lang. May utang ako sa'yo, promise.'", "setup_en": "There's a quiz tomorrow and Bea, your friend who's great at drawing, hasn't reviewed. 'Lend me your answers later, just one peek. I owe you, promise.'", "choices": [{"label": "Hindi pwede. Sabay tayo mag-review.", "label_en": "No way. Let's review together.", "type": "collective", "roll": {"stat": "talino", "dc": 10}, "success": {"text": "Napagani mo siya. Pumasa siyang patas.", "text_en": "You convince her. She passes fairly.", "effects": {"stats": {"talino": 1, "komunidad": 1}, "flags": ["studied_together"]}}, "fail": {"text": "Naubusan kayo ng oras, pero nag-review pa rin.", "text_en": "You ran out of time, but you still reviewed.", "effects": {"flags": ["studied_together"]}}}, {"label": "Sige, kopyahin mo.", "label_en": "Fine, copy it.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1}}, {"label": "Bahala ka.", "label_en": "Do what you want.", "type": "huwag", "roll": null, "effects": {"flags": ["silent_copy"]}}], "callback": "Utang +1 -> Singil seed. silent_copy -> Ch2 Card 4."}, {"id": "ch1_pirma_04", "chapter": 1, "pool": "ch1", "title": "Pirma ni Nanay", "title_en": "Nanay's Signature", "tags": ["family", "padrino", "koneksyon"], "requires": null, "setup": "Field trip bukas, pero kailangan ng pirma ng magulang. Nasa abroad si Nanay at si Tatay ay nasa bukid pa. Sabi ni Ate Pia: 'Ako na ang pipirma. Para lang makasama ka.'", "setup_en": "Field trip tomorrow, but you need a parent's signature. Nanay is abroad and Tatay is still in the fields. Ate Pia says: 'I'll sign it for you. So you can come.'", "choices": [{"label": "Salamat, Ate.", "label_en": "Thanks, Ate.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1, "koneksyon": 1}, "utang": 1}}, {"label": "Magpapaalam ako kay Ma'am nang diretso.", "label_en": "I'll ask Ma'am directly.", "type": "honest", "roll": {"stat": "talino", "dc": 10}, "success": {"text": "Pumayag si Ma'am. Natuto kang magpakatotoo.", "text_en": "Ma'am agrees. You learn to tell it straight.", "effects": {"stats": {"talino": 1}}}, "fail": {"text": "Na-miss mo ang field trip, pero natuto ka.", "text_en": "You miss the trip, but you learn.", "effects": {"stats": {"diskarte": 1}, "flags": ["missed_trip"]}}}, {"label": "Hindi na lang ako sasama.", "label_en": "I'll just stay home.", "type": "huwag", "roll": null, "effects": {"flags": ["stayed_home"]}}], "callback": "Utang +1 -> Singil. missed_trip -> Ch2 (Ma'am remembers honesty)."}, {"id": "ch1_baha_05", "chapter": 1, "pool": "ch1", "title": "Baha sa Kalye", "title_en": "The Flooded Street", "tags": ["barangay", "komunidad", "diskarte"], "requires": null, "setup": "Malakas ang ulan at binaha ang kalye. Si Aling Cora ay nagbubuhat ng mga paninda papasok sa bahay niya, pero hanggang bewang na ang tubig. 'Tulungan mo ako, anak.'", "setup_en": "Heavy rain floods the street. Aling Cora is carrying her goods into her house, but the water is waist-deep. 'Help me, anak.'", "choices": [{"label": "Sige po, buhatin natin.", "label_en": "Yes, ma'am, let's carry them.", "type": "collective", "roll": {"stat": "komunidad", "dc": 10}, "success": {"text": "Nagkasabuyan kayo. Natago nang maayos ang paninda.", "text_en": "You work together. The goods are saved.", "effects": {"stats": {"komunidad": 1}, "flags": ["helped_cora"]}}, "fail": {"text": "Nadulas ka, pero natulungan mo pa rin si Aling Cora.", "text_en": "You slip, but you still help Aling Cora.", "effects": {"stats": {"diskarte": 1}, "flags": ["helped_cora"]}}}, {"label": "May payong at bota ako, gamitin natin.", "label_en": "I have an umbrella and boots, let's use them.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 12}, "success": {"text": "Mayamaya, may tumulong pang isa. Maayos ang tinda.", "text_en": "Soon another neighbor joins. The stall is saved.", "effects": {"stats": {"pera": 1, "komunidad": 1}}}, "fail": {"text": "Nabasa ang gamit mo. Masama ang loob.", "text_en": "Your gear gets soaked. Frustrating.", "effects": {"stats": {"pera": -1}}}}, {"label": "Umuwi na lang ako.", "label_en": "I'll just go home.", "type": "huwag", "roll": null, "effects": {"flags": ["walked_past"]}}], "callback": "helped_cora -> Ch2 Card 5 / Ch3. walked_past -> Ch3."}, {"id": "ch1_tinda_06", "chapter": 1, "pool": "ch1", "title": "Tinda sa Palengke", "title_en": "The Market Stall", "tags": ["family", "padrino", "pera"], "requires": null, "setup": "Hapon na at nagsasara na ang pamilya mo ng tindahan sa palengke. Bumulong ang tanod: 'Maliit lang 'to… pang-merienda lang. Para hindi na maabala.'", "setup_en": "It's late afternoon and your family is closing the market stall. The tanod whispers: 'It's just a little something… for merienda. So no one gets bothered.'", "choices": [{"label": "Sige po, pang-merienda.", "label_en": "Fine, for merienda.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 1, "integridad": -1}, "utang": 1}}, {"label": "Ayusin namin ang pwesto, ngayon na.", "label_en": "We'll fix the spot right now.", "type": "honest", "roll": {"stat": "diskarte", "dc": 12}, "success": {"text": "Nagtodo sila sa inyo. Walang multa.", "text_en": "They hurry. No fine.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Multa. Uboong nang maayos ang pwesto.", "text_en": "A fine. The stall is fixed anyway.", "effects": {"stats": {"pera": -1}, "flags": ["fixed_stall"]}}}, {"label": "Si Nanay na lang ang bahala.", "label_en": "Let Nanay handle it.", "type": "huwag", "roll": null, "effects": {"flags": ["let_nanay"]}}], "callback": "Utang +1 -> Singil. let_nanay -> Ch2 Card 5 / Ch3."}, {"id": "ch2_scholarship_01", "chapter": 2, "pool": "ch2", "title": "Scholarship ni Tita Baby", "title_en": "Tita Baby's Scholarship", "tags": ["education", "padrino"], "requires": null, "setup": "Bukas na ang deadline ng scholarship list. Nag-text si Tita Baby: 'Ako na bahala. Isang tawag lang sa kaibigan ko sa munisipyo.'", "setup_en": "The scholarship list closes tomorrow. Tita Baby texts: 'I'll take care of it. Just one call to my friend at the municipal hall.'", "choices": [{"label": "Salamat po, Tita.", "label_en": "Thank you, Tita.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1, "koneksyon": 1}, "utang": 2}}, {"label": "Mag-aapply ako nang patas.", "label_en": "I'll apply fairly.", "type": "honest", "roll": {"stat": "talino", "dc": 13}, "success": {"text": "Nakapasok ka sa listahan. Patas.", "text_en": "You make the list. Fair and square.", "effects": {"stats": {"talino": 1}}}, "fail": {"text": "Talo ka. Bumaba ang pera.", "text_en": "You lose out. Money gets tighter.", "effects": {"stats": {"pera": -1}}}}, {"label": "Magtanong tayo ng kriteria, kasama ang mga kaklase.", "label_en": "Let's ask for the criteria, with our classmates.", "type": "collective", "roll": {"stat": "komunidad", "dc": 14, "kasama": true}, "success": {"text": "Nagbukas ang criteria. Mas patas para sa lahat.", "text_en": "The criteria are opened. Fairer for everyone.", "effects": {"stats": {"komunidad": 2}, "spokeUp": true}}, "fail": {"text": "Walang nagbago, pero nasabi mo.", "text_en": "Nothing changes, but you spoke up.", "effects": {"spokeUp": true}}}, {"label": "Hindi na lang.", "label_en": "Never mind.", "type": "huwag", "roll": null, "effects": {"stats": {"pera": -1}}}], "callback": "Utang +2 -> Singil. spoke_up -> Organizer career + Ch4."}, {"id": "ch2_org_02", "chapter": 2, "pool": "ch2", "title": "Halalan sa Org", "title_en": "The Org Election", "tags": ["school", "koneksyon", "politika"], "requires": null, "setup": "Halalan na ng student org. Sabi ni Bea: 'Tumakbo ka. Alam kong mananalo ka.' Pero may narinig kang balita — may nag-aalok ng pera para sa boto.", "setup_en": "The student org election is here. Bea says: 'Run. I know you'll win.' But you heard a rumor — someone is offering money for votes.", "choices": [{"label": "Tatakbo ako, patas.", "label_en": "I'll run, fairly.", "type": "honest", "roll": {"stat": "koneksyon", "dc": 13}, "success": {"text": "Nanalo ka nang patas.", "text_en": "You win fairly.", "effects": {"stats": {"koneksyon": 1}, "flags": ["ran_for_org"]}}, "fail": {"text": "Talo ka, pero natuto ka. May sumama sa'yo.", "text_en": "You lose, but you learn. Some stand by you.", "effects": {"stats": {"komunidad": 1}, "flags": ["ran_for_org"]}}}, {"label": "Sabihin kay Kuya Jun, ayusin niya.", "label_en": "Let Kuya Jun fix it.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2, "flags": ["ran_for_org"]}}, {"label": "Suportahan ko na lang si Bea.", "label_en": "I'll just support Bea.", "type": "collective", "roll": {"stat": "komunidad", "dc": 12}, "success": {"text": "Nanalo si Bea. Mas malakas ang samahan.", "text_en": "Bea wins. The org grows stronger.", "effects": {"stats": {"komunidad": 1}, "flags": ["supported_friend"]}}, "fail": {"text": "Talo si Bea, pero nanatili ang samahan.", "text_en": "Bea loses, but the bond remains.", "effects": {}}}, {"label": "Hindi ako makikialam.", "label_en": "I'll stay out of it.", "type": "huwag", "roll": null, "effects": {"flags": ["sat_out"]}}], "callback": "ran_for_org -> Politician career. Utang +2 -> Singil."}, {"id": "ch2_pia_03", "chapter": 2, "pool": "ch2", "title": "Pia, Mas Malaking Pabor", "title_en": "Pia's Bigger Favor", "tags": ["school", "utang", "integridad"], "requires": {"any_flags": ["saw_it"], "utang_min": 1}, "setup": "Lumapit si Pia, kinakabahan. 'Kailangan kong sabihin kay Ma'am Lourdes na ikaw ang kumuha ng ambagan. Hindi ko kaya… pero ikaw, pwede.'", "setup_en": "Pia approaches you, nervous. 'I need to tell Ma'am Lourdes that you took the donation money. I can't do it… but you can.'", "choices": [{"label": "Hindi. Hindi ko 'yan gagawin.", "label_en": "No. I won't do that.", "type": "honest", "roll": {"stat": "integridad", "dc": 13}, "success": {"text": "Nagalit si Pia, pero iginagalang ka niya.", "text_en": "Pia is upset, but she respects you.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Kumalat ang tsismis. Nasaktan ang samahan.", "text_en": "Rumors spread. The group is hurt.", "effects": {"stats": {"komunidad": -1}}}}, {"label": "Sige, ako na ang magsabi.", "label_en": "Fine, I'll be the one to tell.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1, "komunidad": -1}, "utang": 2}}, {"label": "Sabihin natin ang totoo, tayong dalawa.", "label_en": "Let's tell the truth, both of us.", "type": "collective", "roll": {"stat": "komunidad", "dc": 14}, "success": {"text": "Naging maayos ang lahat. Mas malasakit kayo.", "text_en": "It works out. You grow closer.", "effects": {"stats": {"komunidad": 1}, "flags": ["told_truth"]}}, "fail": {"text": "Nadismaya si Ma'am sa inyong dalawa, pero tama ang ginawa ninyo.", "text_en": "Ma'am is disappointed in both of you, but you did right.", "effects": {}}}, {"label": "Bahala ka na, Pia.", "label_en": "Figure it out yourself, Pia.", "type": "huwag", "roll": null, "effects": {"flags": ["left_pia"]}}], "callback": "Utang +2 -> Singil. left_pia -> Ch3."}, {"id": "ch2_bea_04", "chapter": 2, "pool": "ch2", "title": "Bea, Mas Malaking Pabor", "title_en": "Bea's Bigger Favor", "tags": ["school", "utang", "integridad"], "requires": {"any_flags": ["silent_copy"], "utang_min": 1}, "setup": "May malaking exam bukas at hindi pa rin nakapag-review si Bea. 'Isang beses na lang, please. Pag hindi ako pumasa, lagot ako kay Nanay.'", "setup_en": "There's a big exam tomorrow and Bea still hasn't reviewed. 'Just one more time, please. If I fail, Nanay will be furious.'", "choices": [{"label": "Hindi. Pero tutulungan kitang mag-review ngayon.", "label_en": "No. But I'll help you review now.", "type": "collective", "roll": {"stat": "talino", "dc": 12}, "success": {"text": "Pumasa si Bea nang patas.", "text_en": "Bea passes fairly.", "effects": {"stats": {"talino": 1}}}, "fail": {"text": "Pagod kayong dalawa, pero sinubukan mo.", "text_en": "You're both exhausted, but you tried.", "effects": {}}}, {"label": "Sige, kopya ka na lang.", "label_en": "Fine, just copy.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2}}, {"label": "Hindi ko 'yan pipirmahan.", "label_en": "I won't sign off on that.", "type": "honest", "roll": {"stat": "integridad", "dc": 12}, "success": {"text": "Naiintindihan ka ni Bea, kahit nasaktan.", "text_en": "Bea understands, even if hurt.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Nagalit si Bea. Nasaktan ang samahan.", "text_en": "Bea is angry. The bond is hurt.", "effects": {"stats": {"komunidad": -1}}}}, {"label": "Bahala ka.", "label_en": "Do what you want.", "type": "huwag", "roll": null, "effects": {"flags": ["left_bea"]}}], "callback": "Utang +2 -> Singil. left_bea -> Ch3."}, {"id": "ch2_fixer_05", "chapter": 2, "pool": "ch2", "title": "Kuya Jun, ang Fixer", "title_en": "Kuya Jun, the Fixer", "tags": ["barangay", "padrino", "koneksyon"], "requires": null, "setup": "May problema ang pamilya mo — hindi maayos ang papeles sa munisipyo. Lumapit si Kuya Jun, nakangiti. 'Ako na bahala. Kilala ko ang lahat doon.'", "setup_en": "Your family has a problem — the papers at the municipal hall aren't in order. Kuya Jun approaches, smiling. 'I'll take care of it. I know everyone there.'", "choices": [{"label": "Salamat, Kuya.", "label_en": "Thanks, Kuya.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1, "koneksyon": 1}, "utang": 2}}, {"label": "Aayusin ko nang ako lang.", "label_en": "I'll fix it myself.", "type": "honest", "roll": {"stat": "diskarte", "dc": 13}, "success": {"text": "Naayos mo ang papeles nang sarili mo.", "text_en": "You fix the papers on your own.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Naiwan ang papeles. Bumaba ang pera, pero natuto ka.", "text_en": "The papers are delayed. Money drops, but you learn.", "effects": {"stats": {"pera": -1}}}}, {"label": "Isama ko si Aling Cora, baka alam niya.", "label_en": "I'll bring Aling Cora, she might know.", "type": "collective", "roll": {"stat": "komunidad", "dc": 12, "dc_if_flag": {"flag": "helped_cora", "dc": 10}}, "success": {"text": "Tumulong si Aling Cora. Naayos.", "text_en": "Aling Cora helps. It's fixed.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "Naiwan, pero natulungan ka ni Aling Cora.", "text_en": "Still delayed, but Aling Cora helps you understand.", "effects": {}}}, {"label": "Hayaan ko na lang si Nanay.", "label_en": "Let Nanay handle it.", "type": "huwag", "roll": null, "effects": {"flags": ["let_nanay2"]}}], "callback": "Utang +2 -> Singil. Kuya Jun -> recurring fixer (Ch3)."}, {"id": "ch2_vote_06", "chapter": 2, "pool": "ch2", "title": "Bilhan ng Boto", "title_en": "Vote Buying", "tags": ["family", "padrino", "politika"], "requires": null, "setup": "Pista sa baryo at may nag-aalok ng ₱500 sa bawat boto. 'Pang-merienda lang 'to,' sabi ni Kuya Jun. 'Wala naman masama.'", "setup_en": "It's the barrio fiesta and someone is offering ₱500 per vote. 'It's just for merienda,' says Kuya Jun. 'Nothing wrong with that.'", "choices": [{"label": "Sige, isang boto lang.", "label_en": "Fine, one vote.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 1, "integridad": -1}, "utang": 1}}, {"label": "Hindi po, salamat.", "label_en": "No, thank you.", "type": "honest", "roll": {"stat": "integridad", "dc": 12}, "success": {"text": "Naginhawa ka. Tumatagalog ang kumpiyansa mo.", "text_en": "You feel lighter. Your confidence holds.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Nainis si Kuya Jun. Bumaba ang koneksyon.", "text_en": "Kuya Jun is offended. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sabihin ko sa mga kapitbahay.", "label_en": "I'll tell the neighbors.", "type": "collective", "roll": {"stat": "komunidad", "dc": 15}, "success": {"text": "Tatlong kapitbahay ang tumanggi. Tumaas ang tiwala ng bayan.", "text_en": "Three neighbors refuse. The town's trust rises.", "effects": {"tiwala": 1, "spokeUp": true}}, "fail": {"text": "Kakaibo ang tingin. Pero nasabi mo.", "text_en": "Awkward looks. But you spoke.", "effects": {"stats": {"komunidad": -1}, "spokeUp": true}}}, {"label": "Hindi ko problema.", "label_en": "Not my problem.", "type": "huwag", "roll": null, "effects": {"walangKibo": 1}}], "callback": "Utang +1 -> Singil. spoke_up -> Organizer career."}, {"id": "ch2_rico_07", "chapter": 2, "pool": "ch2", "title": "Rico, sa Barkada", "title_en": "Rico and the Barkada", "tags": ["barkada", "komunidad"], "requires": {"any_flags": ["looked_away", "shared_food"]}, "setup": "Na-ospital ang nanay ni Rico at kailangan ng pera. Sabi ng barkada: 'Tulungan natin siya.' Pero ang iba, ayaw madamay.", "setup_en": "Rico's mother is hospitalized and they need money. The barkada says: 'Let's help her.' But some don't want to get involved.", "choices": [{"label": "Tulungan natin siya, lahat tayo.", "label_en": "Let's help her, all of us.", "type": "collective", "roll": {"stat": "komunidad", "dc": 13}, "success": {"text": "Nagkaisa ang barkada. Tulungan ni Rico ang pamilya niya.", "text_en": "The barkada unites. Rico's family is helped.", "effects": {"stats": {"komunidad": 2}, "flags": ["helped_rico"]}}, "fail": {"text": "Hindi sapat, pero nagawa ninyo ang kaya.", "text_en": "Not enough, but you did what you could.", "effects": {"stats": {"komunidad": 1}, "flags": ["helped_rico"]}}}, {"label": "Magbibigay ako ng pera.", "label_en": "I'll give money.", "type": "pera", "roll": null, "effects": {"stats": {"pera": -1, "komunidad": 1}, "flags": ["helped_rico"]}}, {"label": "Tumayo ako para kay Rico.", "label_en": "I'll stand up for Rico.", "type": "honest", "roll": {"stat": "integridad", "dc": 14}, "success": {"text": "Tumayo ka. Sumunod ang iba.", "text_en": "You stand up. Others follow.", "effects": {"stats": {"integridad": 1, "komunidad": 1}, "spokeUp": true}}, "fail": {"text": "Pinagtawanan ka, pero nanatili ka.", "text_en": "They mock you, but you held your ground.", "effects": {"stats": {"komunidad": -1}, "spokeUp": true}}}, {"label": "Hindi ko kaya.", "label_en": "I can't handle this.", "type": "huwag", "roll": null, "effects": {"flags": ["abandoned_rico"]}}], "callback": "helped_rico -> Ch3/Ch4 ally. spoke_up -> Organizer career."}, {"id": "ch2_exam_08", "chapter": 2, "pool": "ch2", "title": "Pagsusulit o Trabaho", "title_en": "Exam or Work", "tags": ["crossroads", "karera"], "requires": null, "setup": "Dumating ang sangandaan. May pagsusulit para sa serbisyo — o pwede kang magtrabaho agad para tumulong sa pamilya. Hindi pwedeng pareho.", "setup_en": "The crossroads arrive. There's a civil service exam — or you can work right away to help the family. You can't do both.", "choices": [{"label": "Kukuha ako ng pagsusulit.", "label_en": "I'll take the exam.", "type": "honest", "roll": {"stat": "talino", "dc": 13}, "success": {"text": "Pumasa ka. Nagbukas ang pinto.", "text_en": "You pass. A door opens.", "effects": {"stats": {"talino": 1}, "flags": ["took_exam_or_followed_family_service"]}}, "fail": {"text": "Teka muna, bumaba ang talino? Hindi — natuto ka. May diskarte ka.", "text_en": "You fail, but you learn. You gain resourcefulness.", "effects": {"stats": {"diskarte": 1}, "flags": ["took_exam_or_followed_family_service"]}}}, {"label": "Sabihin kay Kuya Jun, ayusin ang resulta.", "label_en": "Let Kuya Jun fix the result.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2, "flags": ["took_exam_or_followed_family_service"]}}, {"label": "Magtrabaho na lang ako.", "label_en": "I'll just work.", "type": "ordinary", "roll": null, "effects": {"stats": {"pera": 1, "talino": -1}, "flags": ["went_to_work_early"]}}, {"label": "Hindi ko pa alam.", "label_en": "I don't know yet.", "type": "huwag", "roll": null, "effects": {"flags": ["undecided"]}}], "callback": "took_exam -> Police career. went_to_work_early -> Ordinary Citizen. Utang +2 -> Singil."}, {"id": "ch3_official_consultant_01", "chapter": 3, "pool": "ch3_role", "role": "official", "title": "Ang Consultant", "title_en": "The Consultant", "tags": ["official", "budget"], "requires": null, "setup": "May bagong linya sa budget: 'consultant,' ₱300,000. Walang consultant na nakalista. Sabi ng treasurer: 'Para sa kaibigan ng mayor. Pirma na lang.'", "setup_en": "A new line in the budget: 'consultant,' ₱300,000. No consultant is listed. The treasurer says: 'It's for the mayor's friend. Just sign.'", "choices": [{"label": "Hindi ko pipirmahan.", "label_en": "I won't sign.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Hinadlangan mo. Tumaas ang tiwala sa'yo.", "text_en": "You block it. Trust in you grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Pinipiga ka, pero tumanggi ka pa rin.", "text_en": "You're pressured, but you refused.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sige, pirma na.", "label_en": "Fine, I'll sign.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2, "tiwala": -2}}, {"label": "Ipa-post natin ang budget sa court.", "label_en": "Let's post the budget in public.", "type": "collective", "roll": {"stat": "komunidad", "dc": 16}, "success": {"text": "Naka-post. Tumaas ang tiwala ng bayan.", "text_en": "It's posted. The town's trust rises.", "effects": {"tiwala": 2, "spokeUp": true}}, "fail": {"text": "Hinadlangan, pero nasabi mo.", "text_en": "Blocked, but you spoke up.", "effects": {"spokeUp": true}}}, {"label": "Hindi ko nakita.", "label_en": "I didn't see it.", "type": "huwag", "roll": null, "effects": {"flags": ["ignored_budget"]}}], "callback": "Utang +2 -> Singil. spoke_up -> Ch4."}, {"id": "ch3_official_friend_02", "chapter": 3, "pool": "ch3_role", "role": "official", "title": "Ang Pabor sa Kaibigan", "title_en": "A Friend's Favor", "tags": ["official", "padrino"], "requires": null, "setup": "Lumapit ang kaibigan mong si RC Dizon. 'Isang kontrata lang. Hindi naman mahalaga kung sino ang manalo.' Alam mong siya ang magbubuild.", "setup_en": "Your friend RC Dizon approaches. 'Just one contract. It doesn't matter who wins.' You know his company will build it.", "choices": [{"label": "Hindi. Bidding ang tama.", "label_en": "No. Bidding is the right way.", "type": "honest", "roll": {"stat": "integridad", "dc": 14}, "success": {"text": "Nanatili ang patas na bidding.", "text_en": "Fair bidding holds.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Nagalit si RC. Bumaba ang koneksyon.", "text_en": "RC is angry. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sige, ikaw na.", "label_en": "Fine, it's yours.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2, "flags": ["ghost_seed"], "tiwala": -2}}, {"label": "Ipa-bid natin nang bukas.", "label_en": "Let's bid it openly.", "type": "collective", "roll": {"stat": "komunidad", "dc": 15}, "success": {"text": "Bukas ang bidding. Tumaas ang tiwala.", "text_en": "The bid opens. Trust rises.", "effects": {"tiwala": 1}}, "fail": {"text": "Namanipulaan pa rin, pero sinubukan mo.", "text_en": "It's rigged anyway, but you tried.", "effects": {}}}, {"label": "Bahala na sila.", "label_en": "Leave them to it.", "type": "huwag", "roll": null, "effects": {"flags": ["let_contract"]}}], "callback": "Utang +2 -> Singil. Ghost project -> Ch4."}, {"id": "ch3_official_whistle_03", "chapter": 3, "pool": "ch3_role", "role": "official", "title": "Ang Whistleblower", "title_en": "The Whistleblower", "tags": ["official", "whistleblower"], "requires": null, "setup": "May lumapit sa'yo — isang kawani. 'May ghost project. May resibo pero walang ginawa.' May dala siyang ebidensya, pero natatakot siya.", "setup_en": "Someone approaches you — a clerk. 'There's a ghost project. There's a receipt but nothing was built.' She brought evidence, but she's scared.", "choices": [{"label": "Tulungan kitang i-expose.", "label_en": "Let's expose it together.", "type": "collective", "roll": {"stat": "komunidad", "dc": 16}, "success": {"text": "Nalantad. Tumaas ang tiwala ng bayan.", "text_en": "It's exposed. The town's trust rises.", "effects": {"tiwala": 2, "spokeUp": true}}, "fail": {"text": "Mayamaya, may paghihiganti. Pero nasubukan mo.", "text_en": "Retaliation follows. But you tried.", "effects": {"spokeUp": true}}}, {"label": "I-report ko nang pribado.", "label_en": "I'll report it privately.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Tahimik na imbestigasyon. Tumatakbo.", "text_en": "A quiet investigation begins.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Natabunan. Bumaba ang koneksyon.", "text_en": "It's buried. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sabihin mo kay Kuya Jun.", "label_en": "Tell Kuya Jun.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1}}, {"label": "Wala akong narinig.", "label_en": "I heard nothing.", "type": "huwag", "roll": null, "effects": {"flags": ["ignored_whistle"]}}], "callback": "spoke_up -> Ch4. Ghost project -> Ch4."}, {"id": "ch3_police_checkpoint_01", "chapter": 3, "pool": "ch3_role", "role": "police", "title": "Ang Checkpoint", "title_en": "The Checkpoint", "tags": ["police", "padrino"], "requires": null, "setup": "May nahuli kang driver na walang lisensya. Bumulong siya: 'Settle na lang, sir. Pang-merienda lang.' May dala siyang anak na may sakit.", "setup_en": "You catch a driver without a license. He whispers: 'Let's just settle it, sir. For merienda.' He carries a sick child.", "choices": [{"label": "Hindi. Ticket ang tama.", "label_en": "No. A ticket is right.", "type": "honest", "roll": {"stat": "integridad", "dc": 14}, "success": {"text": "By the book. Tumatagalog ang dangal mo.", "text_en": "By the book. Your honor holds.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Nagmakaawa siya. Nasaktan ka, pero nanatili ka.", "text_en": "He begs. It hurts, but you held.", "effects": {}}}, {"label": "Sige, settle na.", "label_en": "Fine, settle it.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 1, "integridad": -1}, "utang": 1}}, {"label": "Tulungan kitang makuha ang lisensya.", "label_en": "Let's help you get a license.", "type": "collective", "roll": {"stat": "komunidad", "dc": 13}, "success": {"text": "Tumulong ang mga kapitbahay. Maayos ang lisensya.", "text_en": "Neighbors help. The license is sorted.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "Mabagal, pero sinubukan mo.", "text_en": "Slow, but you tried.", "effects": {}}}, {"label": "Bahala ka na.", "label_en": "Figure it out yourself.", "type": "huwag", "roll": null, "effects": {"flags": ["let_driver"]}}], "callback": "Utang +1 -> Singil."}, {"id": "ch3_police_report_02", "chapter": 3, "pool": "ch3_role", "role": "police", "title": "Ang Report", "title_en": "The Report", "tags": ["police", "pressure"], "requires": null, "setup": "Sabi ng superior mo: 'Palambutin mo ang report. Huwag mong banggitin ang pangalan ng konsehal.' Alam mong may nangyari.", "setup_en": "Your superior says: 'Soften the report. Don't mention the councilor's name.' You know something happened.", "choices": [{"label": "Hindi ko babaguhin.", "label_en": "I won't change it.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Natuto ang report nang totoo.", "text_en": "The report stays true.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Prinimahedral ka. Bumaba ang koneksyon.", "text_en": "You're reprimanded. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sige, palambutin ko.", "label_en": "Fine, I'll soften it.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1, "tiwala": -1}}, {"label": "Isama ko ang katotohanan, pero maingat.", "label_en": "I'll keep the truth, but carefully.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 14}, "success": {"text": "Nakapasok ang totoo nang ligtas.", "text_en": "The truth gets in, safely.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "May nakapansin. Bumaba ang koneksyon.", "text_en": "They notice. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Hindi ko alam.", "label_en": "I don't know.", "type": "huwag", "roll": null, "effects": {"flags": ["softened_report"]}}], "callback": "Utang +1 -> Singil."}, {"id": "ch3_police_harass_03", "chapter": 3, "pool": "ch3_role", "role": "police", "title": "Ang Reklamo", "title_en": "The Complaint", "tags": ["police", "justice"], "requires": null, "setup": "May kapitbahay na nagreklamo — hinaharas daw siya ng isang makapangyarihan. 'Takot ako, pero kailangan kong magsalita.'", "setup_en": "A neighbor files a complaint — she says someone powerful is harassing her. 'I'm scared, but I need to speak.'", "choices": [{"label": "Iimbestigahan ko.", "label_en": "I'll investigate.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Tumakbo ang kaso.", "text_en": "The case moves.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Natigil, pero sinubukan mo.", "text_en": "It stalls, but you tried.", "effects": {}}}, {"label": "Tulungan kitang magsampa nang ligtas.", "label_en": "Let's file it safely, together.", "type": "collective", "roll": {"stat": "komunidad", "dc": 15}, "success": {"text": "Ligtas ang pagsampa. Tumaas ang tiwala.", "text_en": "It's filed safely. Trust grows.", "effects": {"stats": {"komunidad": 1}, "spokeUp": true}}, "fail": {"text": "May banta, pero nasubukan mo.", "text_en": "A threat comes, but you tried.", "effects": {"spokeUp": true}}}, {"label": "Sabihin mo na lang kay Kap Eddie.", "label_en": "Just tell Kap Eddie.", "type": "huwag", "roll": null, "effects": {"flags": ["passed_complaint"]}}, {"label": "Wala akong magagawa.", "label_en": "I can't do anything.", "type": "huwag", "roll": null, "effects": {"flags": ["ignored_harass"]}}], "callback": "spoke_up -> Ch4."}, {"id": "ch3_teacher_cement_01", "chapter": 3, "pool": "ch3_role", "role": "teacher", "title": "Ang Semento", "title_en": "The Cement", "tags": ["engineer", "integrity"], "requires": null, "setup": "Pinapapirma ka sa materyales ng proyekto. Alam mong kulang ang semento — mas maraming buhangin. 'Standard 'yan,' sabi ng contractor.", "setup_en": "You're asked to sign off on project materials. You know the cement is short — too much sand. 'That's standard,' says the contractor.", "choices": [{"label": "Hindi ko pipirmahan.", "label_en": "I won't sign.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Tumanggi ka. Tumaas ang dangal mo.", "text_en": "You refuse. Your honor grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Pinipiga ka, pero tumanggi ka.", "text_en": "You're pressured, but you refused.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sige, pirma na.", "label_en": "Fine, I'll sign.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2, "flags": ["ghost_seed"], "tiwala": -2}}, {"label": "Ipa-test natin ang materyales.", "label_en": "Let's test the materials.", "type": "collective", "roll": {"stat": "talino", "dc": 15}, "success": {"text": "Lumabas ang tama. Tumaas ang tiwala.", "text_en": "The truth comes out. Trust rises.", "effects": {"tiwala": 1}}, "fail": {"text": "Hinadlangan, pero sinubokan mo.", "text_en": "Blocked, but you tried.", "effects": {}}}, {"label": "Hindi ko napansin.", "label_en": "I didn't notice.", "type": "huwag", "roll": null, "effects": {"flags": ["signed_cement"]}}], "callback": "Utang +2 -> Singil. Ghost project -> Ch4."}, {"id": "ch3_teacher_receipts_02", "chapter": 3, "pool": "ch3_role", "role": "teacher", "title": "Ang Resibo", "title_en": "The Receipts", "tags": ["teacher", "integrity"], "requires": null, "setup": "Sabi ng principal: 'Itaas mo ang resibo ng classroom fund. Maliit lang, para may pang-ayos tayo.' Alam mong hindi totoo ang numero.", "setup_en": "The principal says: 'Inflate the classroom fund receipts. It's small, so we can do repairs.' You know the number is false.", "choices": [{"label": "Hindi. Totoo ang ilalagay ko.", "label_en": "No. I'll put the truth.", "type": "honest", "roll": {"stat": "integridad", "dc": 14}, "success": {"text": "Tama ang numero. Tumaas ang dangal mo.", "text_en": "The number stays true. Your honor grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Malamlam ang principal. Bumaba ang koneksyon.", "text_en": "The principal turns cold. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sige, itaas ko.", "label_en": "Fine, I'll inflate it.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1, "tiwala": -1}}, {"label": "Ipa-audit natin.", "label_en": "Let's have it audited.", "type": "collective", "roll": {"stat": "talino", "dc": 14}, "success": {"text": "Na-audit. Tumaas ang tiwala.", "text_en": "It's audited. Trust rises.", "effects": {"tiwala": 1}}, "fail": {"text": "Tumanggi sila, pero sinubukan mo.", "text_en": "They resist, but you tried.", "effects": {}}}, {"label": "Bahala na.", "label_en": "Leave it be.", "type": "huwag", "roll": null, "effects": {"flags": ["inflated_receipts"]}}], "callback": "Utang +1 -> Singil."}, {"id": "ch3_teacher_evidence_03", "chapter": 3, "pool": "ch3_role", "role": "teacher", "title": "Ang Ebidensya", "title_en": "The Evidence", "tags": ["teacher", "whistleblower"], "requires": null, "setup": "May estudyanteng lumapit sa'yo na may larawan — may iregularidad sa proyekto ng paaralan. '{{maam}} , hindi ko alam kung kanino ko sasabihin.'", "setup_en": "A student approaches you with a photo — an irregularity in a school project. '{{maam}}, I don't know who to tell.'", "choices": [{"label": "Sasabihin ko sa kinauukulan.", "label_en": "I'll tell the authorities.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Tumakbo ang kaso.", "text_en": "The case opens.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Natigil, pero sinubukan mo.", "text_en": "It stalls, but you tried.", "effects": {}}}, {"label": "Tulungan kitang i-document.", "label_en": "Let's document it together.", "type": "collective", "roll": {"stat": "komunidad", "dc": 14}, "success": {"text": "Solidong ebidensya. Tumaas ang tiwala.", "text_en": "Solid evidence. Trust grows.", "effects": {"stats": {"komunidad": 1}, "spokeUp": true}}, "fail": {"text": "May banta, pero nasubukan mo.", "text_en": "A threat comes, but you tried.", "effects": {"spokeUp": true}}}, {"label": "Sabihin mo kay Kuya Jun.", "label_en": "Tell Kuya Jun.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1}}, {"label": "Huwag ka nang magsalita.", "label_en": "Don't say anything more.", "type": "huwag", "roll": null, "effects": {"flags": ["silenced_student"]}}], "callback": "spoke_up -> Ch4. Ghost project -> Ch4."}, {"id": "ch3_journalist_source_01", "chapter": 3, "pool": "ch3_role", "role": "organizer", "title": "Ang Source", "title_en": "The Source", "tags": ["journalist", "evidence"], "requires": null, "setup": "May source na gustong magsalita tungkol sa ghost project, pero gusto niyang manatiling anonymous. Manipis ang ebidensya mo.", "setup_en": "A source wants to talk about the ghost project, but wants to stay anonymous. Your evidence is thin.", "choices": [{"label": "Ilalabas ko nang maingat.", "label_en": "I'll publish carefully.", "type": "honest", "roll": {"stat": "talino", "dc": 15}, "success": {"text": "Tumatakbo ang istorya.", "text_en": "The story runs.", "effects": {"stats": {"talino": 1}}}, "fail": {"text": "Hinamon, bumaba ang koneksyon.", "text_en": "It's challenged. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Kailangan ko ng mas matibay.", "label_en": "I need stronger evidence.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 14}, "success": {"text": "Matibay na ebidensya.", "text_en": "Solid evidence.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Umiwas ang source, pero natuto ka.", "text_en": "The source backs out, but you learned.", "effects": {}}}, {"label": "Isama ko ang barkada sa pag-verify.", "label_en": "The barkada will help verify.", "type": "collective", "roll": {"stat": "komunidad", "dc": 14}, "success": {"text": "Natiyak ng sama-sama.", "text_en": "Together, you verify it.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "Mabagal, pero matibay.", "text_en": "Slow, but solid.", "effects": {}}}, {"label": "Hindi ko ilalabas.", "label_en": "I won't publish it.", "type": "huwag", "roll": null, "effects": {"flags": ["killed_story"]}}], "callback": "Ghost project -> Ch4."}, {"id": "ch3_journalist_offer_02", "chapter": 3, "pool": "ch3_role", "role": "organizer", "title": "Ang Alok", "title_en": "The Offer", "tags": ["journalist", "threat"], "requires": null, "setup": "May lumapit sa'yo na may alok — pera, para tumigil ka sa pag-iimbestiga. 'Para sa pamilya mo,' sabi niya. Hindi ito banta, pero parang banta.", "setup_en": "Someone approaches you with an offer — money, to stop investigating. 'For your family,' they say. It's not a threat, but it feels like one.", "choices": [{"label": "Hindi ako titigil.", "label_en": "I won't stop.", "type": "honest", "roll": {"stat": "integridad", "dc": 16}, "success": {"text": "Tumuloy ka. Tumaas ang dangal mo.", "text_en": "You continue. Your honor grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Tumindi ang pressure, pero nanatili ka.", "text_en": "Pressure grows, but you held.", "effects": {}}}, {"label": "Tatanggapin ko.", "label_en": "I'll take it.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 2, "integridad": -1}, "utang": 2, "tiwala": -2}}, {"label": "I-document ko ang alok.", "label_en": "I'll document the offer.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 15}, "success": {"text": "May ebidensya ka na.", "text_en": "You have proof.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Denay sila, pero may tala ka.", "text_en": "They deny it, but you took notes.", "effects": {}}}, {"label": "Titigil na lang ako.", "label_en": "I'll just stop.", "type": "huwag", "roll": null, "effects": {"flags": ["stopped_investigating"]}}], "callback": "Utang +2 -> Singil. stopped_investigating -> Ch4 (absent from cascade)."}, {"id": "ch3_journalist_group_03", "chapter": 3, "pool": "ch3_role", "role": "organizer", "title": "Ang Pagod na Grupo", "title_en": "The Tired Group", "tags": ["organizer", "burnout"], "requires": null, "setup": "Ang grupo mo ay pagod na. 'Wala namang nangyayari,' sabi nila. May nagsasabing umalis na lang.", "setup_en": "Your group is tired. 'Nothing ever changes,' they say. Someone suggests just leaving.", "choices": [{"label": "Magpahinga tayo, tapos tuloy.", "label_en": "Let's rest, then continue.", "type": "collective", "roll": {"stat": "komunidad", "dc": 14}, "success": {"text": "Nagpahinga, bumalik mas malakas.", "text_en": "They rest and return stronger.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "May umalis, pero nanatili ang ubod.", "text_en": "Some leave, but the core stays.", "effects": {}}}, {"label": "Mag-isa akong tutuloy.", "label_en": "I'll continue alone.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Tumuloy ka nang mag-isa.", "text_en": "You continue alone.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Pagod na pagod ka na. Burnout.", "text_en": "You burn out.", "effects": {"flags": ["burned_out"]}}}, {"label": "Maghanap ng bagong kaalyado.", "label_en": "Find new allies.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 14}, "success": {"text": "Bagong kaalyado.", "text_en": "New allies.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Mabagal, pero sinubokan mo.", "text_en": "Slow, but you tried.", "effects": {}}}, {"label": "Kayo na lang ang bahala.", "label_en": "You all decide.", "type": "huwag", "roll": null, "effects": {"flags": ["left_group"]}}], "callback": "burned_out -> Ending 8. left_group -> Ch4 (absent)."}, {"id": "ch3_citizen_assembly_01", "chapter": 3, "pool": "ch3_role", "role": "citizen", "title": "Ang Assembly", "title_en": "The Assembly", "tags": ["citizen", "assembly"], "requires": null, "setup": "May barangay assembly tungkol sa baha. 'Pupunta ka ba?' tanong ni Aling Cora. 'Wala namang nangyayari doon,' sabi ng iba.", "setup_en": "There's a barangay assembly about the flood. 'Will you go?' asks Aling Cora. 'Nothing ever happens there,' say the others.", "choices": [{"label": "Pupunta ako.", "label_en": "I'll go.", "type": "collective", "roll": {"stat": "komunidad", "dc": 12}, "success": {"text": "Nagsalita ka. Tumaas ang tiwala.", "text_en": "You speak. Trust grows.", "effects": {"stats": {"komunidad": 1}, "spokeUp": true}}, "fail": {"text": "Hindi ka napansin, pero napunta ka.", "text_en": "You're ignored, but you showed up.", "effects": {"spokeUp": true}}}, {"label": "Magpapadala ako ng sulat.", "label_en": "I'll send a letter.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 12}, "success": {"text": "Nabasa ang sulat.", "text_en": "The letter is read.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Hindi nabasa, pero sinubukan mo.", "text_en": "It's not read, but you tried.", "effects": {}}}, {"label": "Sabihin kay Kuya Jun.", "label_en": "Tell Kuya Jun.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1}}, {"label": "Hindi na lang.", "label_en": "Never mind.", "type": "huwag", "roll": null, "effects": {"flags": ["skipped_assembly"]}}], "callback": "spoke_up -> Ch4. skipped_assembly -> Ch4 (absent)."}, {"id": "ch3_citizen_cosign_02", "chapter": 3, "pool": "ch3_role", "role": "citizen", "title": "Ang Co-sign", "title_en": "The Co-sign", "tags": ["citizen", "padrino"], "requires": null, "setup": "May kapitbahay na humihingi na pumirma ka sa isang kahilingan — para sa tubig. 'Kailangan ko ng maraming pirma.'", "setup_en": "A neighbor asks you to sign a request — for water. 'I need many signatures.'", "choices": [{"label": "Pipirma ako.", "label_en": "I'll sign.", "type": "collective", "roll": {"stat": "komunidad", "dc": 11}, "success": {"text": "Tumulong. Umusad ang kahilingan.", "text_en": "You help. The request moves.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "Natigil, pero pumirma ka.", "text_en": "It stalls, but you signed.", "effects": {}}}, {"label": "Hindi ako pipirma.", "label_en": "I won't sign.", "type": "honest", "roll": {"stat": "integridad", "dc": 11}, "success": {"text": "Tumaas ang dangal mo.", "text_en": "Your honor grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Nasalanta ang kapitbahay. Bumaba ang samahan.", "text_en": "The neighbor is hurt. Ties weaken.", "effects": {"stats": {"komunidad": -1}}}}, {"label": "Sabihin kay Kuya Jun.", "label_en": "Tell Kuya Jun.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1}}, {"label": "Bahala ka na.", "label_en": "Figure it out yourself.", "type": "huwag", "roll": null, "effects": {"flags": ["refused_cosign"]}}], "callback": "Utang +1 -> Singil."}, {"id": "ch3_citizen_vote_03", "chapter": 3, "pool": "ch3_role", "role": "citizen", "title": "Ang ₱500", "title_en": "The ₱500", "tags": ["citizen", "padrino"], "requires": null, "setup": "Gabi bago ang eleksyon. May nag-abot sa'yo ng ₱500. 'Pang-merienda lang. Wala namang masama.'", "setup_en": "The night before the election. Someone hands you ₱500. 'It's just for merienda. Nothing wrong with that.'", "choices": [{"label": "Tatanggapin ko.", "label_en": "I'll take it.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 1, "integridad": -1}, "utang": 1}}, {"label": "Hindi po, salamat.", "label_en": "No, thank you.", "type": "honest", "roll": {"stat": "integridad", "dc": 12}, "success": {"text": "Tumaas ang dangal mo.", "text_en": "Your honor grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Bumaba ang koneksyon.", "text_en": "Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Sabihin ko sa mga kapitbahay.", "label_en": "I'll tell the neighbors.", "type": "collective", "roll": {"stat": "komunidad", "dc": 15}, "success": {"text": "Tatlo ang tumanggi. Tumaas ang tiwala.", "text_en": "Three refuse. Trust rises.", "effects": {"tiwala": 1, "spokeUp": true}}, "fail": {"text": "Bumaba ang samahan, pero nasabi mo.", "text_en": "Ties weaken, but you spoke.", "effects": {"stats": {"komunidad": -1}, "spokeUp": true}}}, {"label": "Hindi ko problema.", "label_en": "Not my problem.", "type": "huwag", "roll": null, "effects": {"walangKibo": 1}}], "callback": "Utang +1 -> Singil. spoke_up -> Ch4."}, {"id": "ch3_shared_sick_01", "chapter": 3, "pool": "ch3_shared", "role": null, "title": "Ang Sakit ni Nanay", "title_en": "Nanay's Illness", "tags": ["family", "pera", "padrino"], "requires": null, "setup": "Na-ospital si Nanay. Kailangan ng pera ngayon na. Lumapit si Tita Baby: 'May kilala akong makakatulong. Isang pirma lang.'", "setup_en": "Nanay is hospitalized. Money is needed now. Tita Baby approaches: 'I know someone who can help. Just one signature.'", "choices": [{"label": "Salamat, Tita.", "label_en": "Thanks, Tita.", "type": "padrino", "roll": null, "effects": {"stats": {"pera": 2, "integridad": -1}, "utang": 2}}, {"label": "Maghahanap ako ng paraan.", "label_en": "I'll find a way.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 14}, "success": {"text": "May paraan. Tumaas ang diskarte.", "text_en": "You find a way. Resourcefulness grows.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "Bumaba ang pera, pero sinubokan mo.", "text_en": "Money drops, but you tried.", "effects": {"stats": {"pera": -1}}}}, {"label": "Hihingi ako ng tulong sa barkada.", "label_en": "I'll ask the barkada.", "type": "collective", "roll": {"stat": "komunidad", "dc": 13}, "success": {"text": "Nagbayanihan. Nakalikom.", "text_en": "They chip in. Funds raised.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "Hindi sapat, pero tumulong.", "text_en": "Not enough, but they helped.", "effects": {}}}, {"label": "Bahala na ang ospital.", "label_en": "Let the hospital handle it.", "type": "huwag", "roll": null, "effects": {"flags": ["couldnt_pay"]}}], "callback": "Utang +2 -> Singil. (Sympathetic reason for padrino.)"}, {"id": "ch3_shared_road_02", "chapter": 3, "pool": "ch3_shared", "role": null, "title": "Ang Sirang Kalsada", "title_en": "The Broken Road", "tags": ["barangay", "komunidad"], "requires": null, "setup": "Baha na naman sa kalye ninyo. Walang gumagawa. Sabi ni Kap Eddie: 'Mag-aantay tayo ng pondo.'", "setup_en": "The street floods again. No one acts. Kap Eddie says: 'We'll wait for funds.'", "choices": [{"label": "Mag-organize tayo ng bayanihan.", "label_en": "Let's organize a bayanihan.", "type": "collective", "roll": {"stat": "komunidad", "dc": 14}, "success": {"text": "Nagbayanihan. Naayos ang kalye. Tumaas ang tiwala.", "text_en": "You organize. The street is fixed. Trust grows.", "effects": {"stats": {"komunidad": 1}, "spokeUp": true}}, "fail": {"text": "Hindi sapat, pero nasabi mo.", "text_en": "Not enough, but you spoke up.", "effects": {"spokeUp": true}}}, {"label": "Magreklamo ako kay Kap Eddie.", "label_en": "I'll complain to Kap Eddie.", "type": "honest", "roll": {"stat": "koneksyon", "dc": 13}, "success": {"text": "Nangako si Kap. Tumaas ang koneksyon.", "text_en": "Kap promises. Ties strengthen.", "effects": {"stats": {"koneksyon": 1}}}, "fail": {"text": "Walang nangyari, pero sinubokan mo.", "text_en": "Nothing happens, but you tried.", "effects": {}}}, {"label": "Sabihin kay Kuya Jun.", "label_en": "Tell Kuya Jun.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 1}}, {"label": "Mag-antay na lang.", "label_en": "Just wait.", "type": "huwag", "roll": null, "effects": {"flags": ["waited"]}}], "callback": "spoke_up -> Ch4. Utang +1 -> Singil."}, {"id": "ch3_shared_boss_03", "chapter": 3, "pool": "ch3_shared", "role": null, "title": "Ang Utos ng Boss", "title_en": "The Boss's Order", "tags": ["work", "integrity"], "requires": null, "setup": "Sabi ng boss mo: 'Baguhin mo ang numero. Maliit lang, walang makakaalam.' Kung hindi, baka mawala ang trabaho mo.", "setup_en": "Your boss says: 'Change the number. It's small, no one will know.' If you don't, you might lose your job.", "choices": [{"label": "Hindi ko babaguhin.", "label_en": "I won't change it.", "type": "honest", "roll": {"stat": "integridad", "dc": 15}, "success": {"text": "Nanatili ka. May trabaho ka pa.", "text_en": "You hold. You keep your job.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Bumaba ang pera, pero nanatili ka.", "text_en": "Money drops, but you held.", "effects": {"stats": {"pera": -1}}}}, {"label": "Sige, babaguhin ko.", "label_en": "Fine, I'll change it.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1, "pera": 1}, "utang": 1}}, {"label": "I-document ko muna.", "label_en": "I'll document it first.", "type": "diskarte", "roll": {"stat": "diskarte", "dc": 14}, "success": {"text": "May ebidensya ka.", "text_en": "You have proof.", "effects": {"stats": {"diskarte": 1}}}, "fail": {"text": "May nakapansin. Bumaba ang koneksyon.", "text_en": "The boss notices. Ties weaken.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Bahala na.", "label_en": "Leave it be.", "type": "huwag", "roll": null, "effects": {"flags": ["changed_numbers"]}}], "callback": "Utang +1 -> Singil."}, {"id": "ch3_shared_pia_04", "chapter": 3, "pool": "ch3_shared", "role": null, "title": "Ang Pagbabalik ni Pia", "title_en": "Pia's Return", "tags": ["callback", "loyalty"], "requires": null, "setup": "Nagkita kayo ni Pia pagkatapos ng maraming taon. 'May kailangan ako,' sabi niya. 'Isang pirma lang. Para sa kapatid ko.'", "setup_en": "You meet Pia again after many years. 'I need something,' she says. 'Just one signature. For my sibling.'", "choices": [{"label": "Sige, pipirma ako.", "label_en": "Fine, I'll sign.", "type": "padrino", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": 2}}, {"label": "Hindi ko kaya.", "label_en": "I can't.", "type": "honest", "roll": {"stat": "integridad", "dc": 13}, "success": {"text": "Tumaas ang dangal mo.", "text_en": "Your honor grows.", "effects": {"stats": {"integridad": 1}}}, "fail": {"text": "Nasalanta si Pia. Bumaba ang samahan.", "text_en": "Pia is hurt. Ties weaken.", "effects": {"stats": {"komunidad": -1}}}}, {"label": "Tulungan kitang mahanap ng ibang paraan.", "label_en": "Let's find another way.", "type": "collective", "roll": {"stat": "komunidad", "dc": 13}, "success": {"text": "May nakitang paraan.", "text_en": "You find another way.", "effects": {"stats": {"komunidad": 1}}}, "fail": {"text": "Hindi sapat, pero sinubokan mo.", "text_en": "Not enough, but you tried.", "effects": {}}}, {"label": "Hindi na kita kilala.", "label_en": "I don't know you anymore.", "type": "huwag", "roll": null, "effects": {"flags": ["rejected_pia"]}}], "callback": "Utang +2 -> Singil."}, {"id": "ch3_singil_sign_01", "chapter": 3, "pool": "ch3_singil", "role": null, "title": "Ang Pirma", "title_en": "The Signature", "tags": ["singil", "utang"], "requires": {"utang_min": 3}, "setup": "Tumawag si Tita Baby. 'Anak, may papel lang… pirma lang. Alam mo namang tumulong ako sa'yo noon.'", "setup_en": "Tita Baby calls. 'Anak, it's just a paper… just a signature. You know I helped you back then.'", "choices": [{"label": "Pipirma ako.", "label_en": "I'll sign.", "type": "comply", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": -2, "tiwala": -2, "complied": true}}, {"label": "Hindi ako pipirma.", "label_en": "I won't sign.", "type": "honest", "roll": {"stat": "integridad", "dc": 10, "dc_plus_utang": true, "kasama": true, "echoes": true}, "success": {"text": "Nalinawan. Nawala ang utang. Tumaas ang samahan.", "text_en": "It clears. The debt is gone. Bonds grow.", "effects": {"stats": {"komunidad": 1}, "utangClear": true}}, "fail": {"text": "Nasalanta ang koneksyon. Nanatili ang utang.", "text_en": "Ties are damaged. The debt stays.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Hihingi ako ng tulong kay Nurse Lea.", "label_en": "I'll ask Nurse Lea for help.", "type": "collective", "roll": {"stat": "komunidad", "dc": 12, "kasama": true, "echoes": true}, "success": {"text": "Tumulong si Nurse Lea. Nawala ang utang.", "text_en": "Nurse Lea helps. The debt clears.", "effects": {"stats": {"komunidad": 1}, "utangClear": true}}, "fail": {"text": "Hindi agad, pero may sumama.", "text_en": "Not yet, but someone stands with you.", "effects": {}}}, {"label": "Pag-iisipan ko.", "label_en": "I'll think about it.", "type": "huwag", "roll": null, "effects": {"utang": 1}}], "callback": "Debt cleared -> Ch4 with lighter burden."}, {"id": "ch3_singil_fixer_02", "chapter": 3, "pool": "ch3_singil", "role": null, "title": "Ang Pirma ni Kuya Jun", "title_en": "Kuya Jun's Signature", "tags": ["singil", "utang", "fixer"], "requires": {"utang_min": 3}, "setup": "Sabi ni Kuya Jun: 'Isang pirma lang. Vouch mo lang ako sa isang proyekto. Hindi ito malaking bagay.'", "setup_en": "Kuya Jun says: 'Just one signature. Just vouch for me on a project. It's no big deal.'", "choices": [{"label": "Pipirma ako.", "label_en": "I'll sign.", "type": "comply", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": -2, "tiwala": -2, "complied": true}}, {"label": "Hindi.", "label_en": "No.", "type": "honest", "roll": {"stat": "integridad", "dc": 10, "dc_plus_utang": true, "kasama": true, "echoes": true}, "success": {"text": "Nawala ang utang. Tumaas ang samahan.", "text_en": "The debt clears. Bonds grow.", "effects": {"stats": {"komunidad": 1}, "utangClear": true}}, "fail": {"text": "Bumaba ang pera. Nanatili ang utang.", "text_en": "Money drops. The debt stays.", "effects": {"stats": {"pera": -1}}}}, {"label": "Isama ko ang barkada.", "label_en": "I'll bring the barkada.", "type": "collective", "roll": {"stat": "komunidad", "dc": 12, "kasama": true, "echoes": true}, "success": {"text": "Tumulong ang barkada. Nawala ang utang.", "text_en": "The barkada helps. The debt clears.", "effects": {"stats": {"komunidad": 1}, "utangClear": true}}, "fail": {"text": "Hindi agad, pero may sumama.", "text_en": "Not yet, but someone stands with you.", "effects": {}}}, {"label": "Pag-iisipan ko.", "label_en": "I'll think about it.", "type": "huwag", "roll": null, "effects": {"utang": 1}}], "callback": "Debt cleared -> Ch4."}, {"id": "ch3_singil_bea_03", "chapter": 3, "pool": "ch3_singil", "role": null, "title": "Ang Utang ni Bea", "title_en": "Bea's Debt", "tags": ["singil", "utang", "callback"], "requires": {"utang_min": 3}, "setup": "Tumawag si Bea. 'Naalala mo ang utang mo sa akin? Kailangan ko ng pabor — ngayon na.'", "setup_en": "Bea calls. 'Remember the favor you owe me? I need one — right now.'", "choices": [{"label": "Sige, gagawin ko.", "label_en": "Fine, I'll do it.", "type": "comply", "roll": null, "effects": {"stats": {"integridad": -1}, "utang": -2, "tiwala": -1, "complied": true}}, {"label": "Hindi.", "label_en": "No.", "type": "honest", "roll": {"stat": "integridad", "dc": 10, "dc_plus_utang": true, "kasama": true, "echoes": true}, "success": {"text": "Nawala ang utang. Tumaas ang samahan.", "text_en": "The debt clears. Bonds grow.", "effects": {"stats": {"komunidad": 1}, "utangClear": true}}, "fail": {"text": "Nasalanta ang koneksyon. Nanatili ang utang.", "text_en": "Ties are damaged. The debt stays.", "effects": {"stats": {"koneksyon": -1}}}}, {"label": "Hihingi ako ng tulong.", "label_en": "I'll ask for help.", "type": "collective", "roll": {"stat": "komunidad", "dc": 12, "kasama": true, "echoes": true}, "success": {"text": "May sumama. Nawala ang utang.", "text_en": "Someone joins. The debt clears.", "effects": {"stats": {"komunidad": 1}, "utangClear": true}}, "fail": {"text": "Hindi agad, pero may sumama.", "text_en": "Not yet, but someone stands with you.", "effects": {}}}, {"label": "Hindi pa ngayon.", "label_en": "Not now.", "type": "huwag", "roll": null, "effects": {"utang": 1}}], "callback": "Debt cleared -> Ch4."}, {"id": "ch4_flood_01", "chapter": 4, "pool": "ch4", "role": null, "title": "Baha", "title_en": "The Flood", "tags": ["climax", "flood"], "requires": null, "systemic": true, "setup": "Tatlong araw ng ulan at bumaha ang bayan. Ang proyektong 'tapos na' tatlong taon na ang nakalipas — wala. Ang arko, maganda. Nagkukumpol ang mga tao sa barangay hall, basang-basa at galit.", "setup_en": "Three days of rain and the town floods. The project that was 'finished' three years ago — doesn't exist. The arch is lovely. People gather at the barangay hall, soaked and angry.", "choices": [{"label": "Magsasalita ako nang una.", "label_en": "I'll speak first.", "type": "honest", "roll": {"stat": "integridad", "dc": 18, "systemic": true}, "success": {"text": "Tumahimik ang lahat. Ikaw ang unang boses. May sumunod.", "text_en": "The room goes quiet. You are the first voice. Someone follows.", "effects": {"voices": 1, "spokeFirst": true}}, "fail": {"text": "Umay ka muna, pero nagsalita ka. Ikaw ang unang boses.", "text_en": "It comes out rough, but you spoke. You are the first voice.", "effects": {"voices": 1, "spokeFirst": true}}}, {"label": "Maghihintay ako kung sino ang magsasalita.", "label_en": "I'll wait to see who speaks.", "type": "huwag", "roll": null, "effects": {}}, {"label": "Dadalhin ko ang mga kapitbahay ko.", "label_en": "I'll bring my neighbors.", "type": "collective", "roll": {"stat": "komunidad", "dc": 16, "systemic": true, "kasama": true, "echoes": true}, "success": {"text": "Dumating ang mga kapitbahay. Dalawang boses pa.", "text_en": "The neighbors arrive. Two more voices.", "effects": {"voices": 2, "spokeUp": true}}, "fail": {"text": "Isang kapitbahay ang sumama. Boses pa rin.", "text_en": "One neighbor joins. A voice anyway.", "effects": {"voices": 1, "spokeUp": true}}}, {"label": "Aalis na lang ako.", "label_en": "I'll just leave.", "type": "escape", "roll": null, "effects": {"walangKibo": 1}}], "callback": "Voice count begins. Echoes add voices."}, {"id": "ch4_assembly_02", "chapter": 4, "pool": "ch4", "role": null, "title": "Ang Pagkukumpol", "title_en": "The Gathering", "tags": ["climax", "assembly"], "requires": null, "systemic": true, "setup": "Nagsalita si Nurse Lea — ang unang boses. 'Hindi ito aksidente. May resibo, pero walang proyekto.' Tahimik ang lahat. Hinihintay kung sino ang susunod.", "setup_en": "Nurse Lea speaks — the first voice. 'This wasn't an accident. There's a receipt, but no project.' Everyone is quiet. They wait to see who speaks next.", "choices": [{"label": "Susuporta ako kay Nurse Lea.", "label_en": "I'll support Nurse Lea.", "type": "collective", "roll": {"stat": "komunidad", "dc": 16, "systemic": true, "kasama": true, "echoes": true}, "success": {"text": "Sumama ka. Sumama rin ang mga Galit na Kapitbahay.", "text_en": "You join. The Angry Neighbors join too.", "effects": {"voices": 2, "spokeUp": true}}, "fail": {"text": "Sumama ka. Isang boses pa.", "text_en": "You join. One more voice.", "effects": {"voices": 1, "spokeUp": true}}}, {"label": "Magsasalita ako nang mag-isa.", "label_en": "I'll speak alone.", "type": "honest", "roll": {"stat": "integridad", "dc": 17, "systemic": true}, "success": {"text": "Tumayo ka nang mag-isa. Isang boses pa.", "text_en": "You stand alone. One more voice.", "effects": {"voices": 1, "spokeUp": true}}, "fail": {"text": "Mahirap, pero nagsalita ka. Isang boses pa.", "text_en": "It's hard, but you spoke. One more voice.", "effects": {"voices": 1, "spokeUp": true}}}, {"label": "Mananatili akong tahimik.", "label_en": "I'll stay quiet.", "type": "huwag", "roll": null, "effects": {}}], "callback": "Voice count +1/+2. Cascade builds toward Worried Parents."}, {"id": "ch4_evidence_03", "chapter": 4, "pool": "ch4", "role": null, "title": "Ang Ebidensya", "title_en": "The Evidence", "tags": ["climax", "evidence"], "requires": null, "systemic": true, "setup": "May nagpakita ng ebidensya — ang supply log, ang resibo, ang larawan ng walang ginawa. Hindi na ito usap lang. Totoo na ito.", "setup_en": "Someone shows evidence — the supply log, the receipt, the photo of the empty site. This isn't talk anymore. It's real.", "choices": [{"label": "Ipapakita ko ang ebidensya ko.", "label_en": "I'll present my evidence.", "type": "honest", "roll": {"stat": "talino", "dc": 16, "systemic": true}, "success": {"text": "Hindi na matatanggi. Sumama ang mga Nag-aalalang Magulang.", "text_en": "It's undeniable. The Worried Parents join.", "effects": {"voices": 2, "spokeUp": true}}, "fail": {"text": "Hinamon ka, pero nagsalita ka. Isang boses pa.", "text_en": "You're questioned, but you spoke. One more voice.", "effects": {"voices": 1, "spokeUp": true}}}, {"label": "Isama ko ang mga echo ng ibang tao.", "label_en": "I'll bring the echoes of others.", "type": "collective", "roll": null, "effects": {"voices": 2, "spokeUp": true, "usesEchoes": 2}}, {"label": "Mananatili akong tahimik.", "label_en": "I'll stay quiet.", "type": "huwag", "roll": null, "effects": {}}], "callback": "Voice count +1/+2. Cautious Vendors may join."}, {"id": "ch4_morning_04", "chapter": 4, "pool": "ch4", "role": null, "title": "Ang Umaga", "title_en": "The Morning", "tags": ["climax", "decision"], "requires": null, "systemic": true, "setup": "Ang mga boses ay dumami. Ang Silent Majority ay nagsalita na. Ang bayan ay kailangang magdesisyon — reporma o tanggapin ang dati.", "setup_en": "The voices grow. The Silent Majority has spoken. The town must decide — reform, or accept the old way.", "choices": [{"label": "Reporma. Ngayon na.", "label_en": "Reform. Now.", "type": "collective", "roll": {"stat": "komunidad", "dc": 18, "systemic": true, "kasama": true, "echoes": true}, "success": {"text": "Nagbago ang bayan. Sabay-sabay.", "text_en": "The town changes. Together.", "effects": {"reform": true}}, "fail": {"text": "Hindi ganap, pero nagsimula. Sumalakong ka.", "text_en": "Not complete, but it begins. You stepped up.", "effects": {"voices": 1, "spokeUp": true}}}, {"label": "Unti-unti lang.", "label_en": "Slowly.", "type": "honest", "roll": {"stat": "integridad", "dc": 16, "systemic": true}, "success": {"text": "Unti-unting reporma. Tumatakbo.", "text_en": "Slow reform. It moves.", "effects": {"reform": true}}, "fail": {"text": "Status quo, pero nagsalita ka.", "text_en": "Status quo, but you spoke.", "effects": {"voices": 1, "spokeUp": true}}}, {"label": "Tanggapin na lang ang dati.", "label_en": "Just accept the old way.", "type": "huwag", "roll": null, "effects": {"walangKibo": 1}}], "callback": "Determines ending (Reform vs status quo). Leads to final screen."}], "endings": [{"id": 1, "title": "Ang Kapitang Hindi Yumuko", "title_en": "The Captain Who Didn't Bow", "career": "official", "condition": "Integridad high, Utang low", "text": "Hindi ka yumuko. Sa huling assembly, ikaw ang nagsalita nang una — at ang bayan ay sumunod. Hindi ka naging bayani. Naging halimbawa ka lang. At minsan, sapat na 'yon.", "text_en": "You didn't bow. At the final assembly, you spoke first — and the town followed. You weren't a hero. You were an example. And sometimes, that's enough."}, {"id": 2, "title": "Ang Pirma", "title_en": "The Signature", "career": "official", "condition": "Utang high, complied with Singil", "text": "Pumirma ka. Alam mong mali, pero may nanay kang may sakit, may utang kang binabayaran. Hindi ka masamang tao. Isa ka lang taong napagod. Ang bayan ay nagpatuloy — pero ikaw, hindi na makatulog.", "text_en": "You signed. You knew it was wrong, but your mother was sick, and you were paying a debt. You're not a bad person. You were just tired. The town moved on — but you stopped sleeping."}, {"id": 3, "title": "Ang Badge", "title_en": "The Badge", "career": "police", "condition": "Integridad high, spoke up", "text": "Suot mo ang badge nang may dangal. Sa huling gabi, tumayo ka sa gitna ng assembly at nagsalita. Ang ilan ay nagalit. Ang bayan ay nakinig. Ang badge ay hindi na mabigat.", "text_en": "You wear the badge with honor. On the last night, you stood in the middle of the assembly and spoke. Some were angry. The town listened. The badge isn't heavy anymore."}, {"id": 4, "title": "Ang Sumunod", "title_en": "The Follower", "career": "police", "condition": "complied under pressure", "text": "Sinunod mo ang utos. Mas madali 'yon. Pero sa gabi, naaalala mo ang mukha ng kapitbahay na humingi ng tulong. Hindi ka masama. Natatakot ka lang. At ang takot, minsan, ay sapat na para sumunod.", "text_en": "You followed orders. That was easier. But at night, you remember the face of the neighbor who asked for help. You're not bad. You were just afraid. And sometimes, fear is enough to make you comply."}, {"id": 5, "title": "Ang Tamang Semento", "title_en": "The Right Cement", "career": "teacher", "condition": "refused or reported", "text": "Tumanggi kang pumirma. Ang semento ay tama, ang resibo ay totoo. Nawalan ka ng kaibigan sa munisipyo, pero nakuha mo ang sarili mo. Ang mga estudyante mo ay natuto — hindi lang sa aralin, kundi sa halimbawa.", "text_en": "You refused to sign. The cement is right, the receipt is true. You lost a friend at the hall, but you found yourself. Your students learned — not just from lessons, but from example."}, {"id": 6, "title": "Ang Pumikit", "title_en": "The One Who Looked Away", "career": "teacher", "condition": "stayed silent", "text": "Pumikit ka. Hindi dahil gusto mo, kundi dahil pagod ka na. Ang proyekto ay itinayo nang mali, at ang baha ay dumating. Minsan, ang katahimikan ay isang pagpili rin — at may bayad ito.", "text_en": "You looked away. Not because you wanted to, but because you were tired. The project was built wrong, and the flood came. Sometimes silence is also a choice — and it has a price."}, {"id": 7, "title": "Ang Boses", "title_en": "The Voice", "career": "organizer", "condition": "cascade succeeded", "text": "Ang boses mo ay hindi nag-iisa. Sa assembly, ang isa ay naging marami. Ang bayan ay nagbago — hindi dahil sa'yo, kundi dahil sa lahat ng nagsalita. Ikaw ay isa lang sa kanila. At 'yon ang buong punto.", "text_en": "Your voice wasn't alone. At the assembly, one became many. The town changed — not because of you, but because of everyone who spoke. You were just one of them. And that's the whole point."}, {"id": 8, "title": "Ang Pagod na Boses", "title_en": "The Tired Voice", "career": "organizer", "condition": "acted alone and burned out", "text": "Nagsalita ka nang mag-isa, at napagod ka. Walang sumama, kaya walang nagbago. Hindi ito pagkabigo mo — ito ang gastos ng pagkilos nang mag-isa. Ang bayan ay naghintay ng iba. Sana ay may sumama.", "text_en": "You spoke alone, and you burned out. No one joined, so nothing changed. This isn't your failure — it's the cost of acting alone. The town waited for others. I wish someone had joined you."}, {"id": 9, "title": "Ang Sumama", "title_en": "The One Who Joined", "career": "citizen", "condition": "joined the cascade", "text": "Hindi ka nagsalita nang una. Pero nang may nagsalita, sumama ka. At ang pagsama mo ang naging dahilan kung bakit naging marami ang boses. Hindi ka bayani. Isa kang kapitbahay. At ang kapitbahay, minsan, ang pinakamahalaga.", "text_en": "You didn't speak first. But when someone did, you joined. And your joining is why the voices became many. You're not a hero. You're a neighbor. And neighbors, sometimes, are the most important thing."}, {"id": 10, "title": "Ang Nanood", "title_en": "The Watcher", "career": "citizen", "condition": "stayed silent", "text": "Nanood ka lang. Ang baha ay dumating at umalis. Ang bayan ay nagbago — o hindi. Hindi ka masama. Isa ka lang taong hindi pa handa. Ang pinto ay bukas pa rin.", "text_en": "You just watched. The flood came and went. The town changed — or didn't. You're not bad. You're just someone who wasn't ready yet. The door is still open."}], "echoes": [{"id": "echo_01", "text": "Nurse Lea leaked the supply log: +1d6 once.", "text_en": "Nurse Lea leaked the supply log: +1d6 once."}, {"id": "echo_02", "text": "Aling Cora kept the receipts: +1d6 once.", "text_en": "Aling Cora kept the receipts: +1d6 once."}, {"id": "echo_03", "text": "A teacher photographed the empty site: +1d6 once.", "text_en": "A teacher photographed the empty site: +1d6 once."}, {"id": "echo_04", "text": "The barkada chipped in for the printing: +1d6 once.", "text_en": "The barkada chipped in for the printing: +1d6 once."}, {"id": "echo_05", "text": "Kap Eddie looked the other way — for once: +1d6 once.", "text_en": "Kap Eddie looked the other way — for once: +1d6 once."}, {"id": "echo_06", "text": "Someone posted the budget on the court wall: +1d6 once.", "text_en": "Someone posted the budget on the court wall: +1d6 once."}, {"id": "echo_07", "text": "The vendor association kept the records: +1d6 once.", "text_en": "The vendor association kept the records: +1d6 once."}, {"id": "echo_08", "text": "A student drew the missing project: +1d6 once.", "text_en": "A student drew the missing project: +1d6 once."}, {"id": "echo_09", "text": "The tanod's nephew testified: +1d6 once.", "text_en": "The tanod's nephew testified: +1d6 once."}, {"id": "echo_10", "text": "The OFW family sent money for the assembly: +1d6 once.", "text_en": "The OFW family sent money for the assembly: +1d6 once."}, {"id": "echo_11", "text": "Ma'am Lourdes kept her old lesson plans: +1d6 once.", "text_en": "Ma'am Lourdes kept her old lesson plans: +1d6 once."}, {"id": "echo_12", "text": "The whole street signed the petition: +1d6 once.", "text_en": "The whole street signed the petition: +1d6 once."}], "finalAsks": [{"id": "small_town", "label": "Maliit na bayan / rural na barangay", "label_en": "Small town / rural barangay", "text": "Attend your next barangay assembly. Ask to see the posted budget. Bring one neighbor.", "text_en": "Attend your next barangay assembly. Ask to see the posted budget. Bring one neighbor."}, {"id": "city", "label": "Barangay sa lungsod", "label_en": "City barangay", "text": "Find your barangay's posted budget (barangay hall wall or website). Ask one question about it at the next assembly.", "text_en": "Find your barangay's posted budget (barangay hall wall or website). Ask one question about it at the next assembly."}, {"id": "school", "label": "Komunidad ng paaralan", "label_en": "School community", "text": "Ask your school's PTA or SGC to post the budget. Offer to help make it readable.", "text_en": "Ask your school's PTA or SGC to post the budget. Offer to help make it readable."}, {"id": "general", "label": "Heneral", "label_en": "General", "text": "Ask one local official one question about a local project. Write down the answer. Share it with one neighbor.", "text_en": "Ask one local official one question about a local project. Write down the answer. Share it with one neighbor."}], "backgrounds": [{"roll": 1, "id": "mahirap", "name": "Mahirap na pamilya", "name_en": "Low-income family", "bonus": {"komunidad": 2, "diskarte": 1}, "penalty": {"pera": -1, "talino": -1}, "text": "Mahirap na pamilya. Close ang samahan, pero tight ang pera.", "text_en": "Low-income family. Close bonds, tight money."}, {"roll": 2, "id": "vendor", "name": "Pamilya ng vendor/driver", "name_en": "Vendor/driver family", "bonus": {"diskarte": 2}, "penalty": {"koneksyon": -1}, "text": "Pamilya ng vendor/driver. Marunong makibagay, walang koneksyon.", "text_en": "Vendor/driver family. Street-smart, no connections."}, {"roll": 3, "id": "ofw", "name": "Pamilyang OFW", "name_en": "OFW family", "bonus": {"pera": 2}, "penalty": {"komunidad": -1}, "text": "Pamilyang OFW. May padala, pero malayo ang pamilya.", "text_en": "OFW family. Remittances come, but family is far."}, {"roll": 4, "id": "kawani", "name": "Pamilya ng kawani", "name_en": "Government employee family", "bonus": {"koneksyon": 2}, "penalty": {}, "bonus_note": "More favors offered early (higher Utang risk).", "penalty_note": "More favors offered early (higher Utang risk).", "text": "Pamilya ng kawani. Maraming kakilala, madaming alok na pabor.", "text_en": "Government employee family. Many acquaintances, many favors offered."}, {"roll": 5, "id": "negosyo", "name": "Pamilyang may negosyo", "name_en": "Business-owning family", "bonus": {"pera": 2, "koneksyon": 1}, "penalty": {"komunidad": -1}, "text": "Pamilyang may negosyo. Komportable, pero abala.", "text_en": "Business-owning family. Comfortable, but busy."}, {"roll": 6, "id": "guro", "name": "Pamilyang guro/propesyonal", "name_en": "Teacher/professional family", "bonus": {"talino": 2, "integridad": 1}, "penalty": {"pera": -1}, "text": "Pamilyang guro/propesyonal. Masinop sa aralin, tight ang pera.", "text_en": "Teacher/professional family. Strong in study, tight money."}], "eras": [{"min": 0, "max": 29, "id": "mabulok", "name": "Mabulok", "name_en": "Rotten", "dc_mod": 2, "desc": "Systemic DCs +2. Ang bayan ay parang nabulok.", "desc_en": "Systemic DCs +2. The town feels rotten."}, {"min": 30, "max": 59, "id": "karaniwan", "name": "Karaniwan", "name_en": "Ordinary", "dc_mod": 0, "desc": "Baseline. Karaniwang bayan.", "desc_en": "Baseline. An ordinary town."}, {"min": 60, "max": 84, "id": "gumigising", "name": "Gumigising", "name_en": "Awakening", "dc_mod": -2, "desc": "Systemic DCs −2. Mas madami ang echo. Ang bayan ay gumigising.", "desc_en": "Systemic DCs −2. More echoes. The town is waking up."}, {"min": 85, "max": 100, "id": "bagong_umaga", "name": "Bagong Umaga", "name_en": "New Morning", "dc_mod": -2, "desc": "Special cards unlock. Kwento ni Kap Eddie ay nagbago.", "desc_en": "Special cards unlock. Kap Eddie's story changes."}]};
